        mockManifest.setLabels(labels);
        when(manifestService.loadForUpdate(eq(NAMESPACE_ID), eq(SKILL_NAME))).thenReturn(mockManifest);

        // When
        invokePrivatePublishApprovedBySystem(NAMESPACE_ID, SKILL_NAME, VERSION, updateLatestLabel);

        // Then
        verify(resourceManager).doSystemPublish(NAMESPACE_ID, SKILL_NAME, RESOURCE_TYPE_SKILL, VERSION, updateLatestLabel);
        verify(manifestService).loadForUpdate(NAMESPACE_ID, SKILL_NAME);
        assertTrue(mockManifest.getVersions().containsKey(VERSION));
